import UIKit
import Flutter
import awesome_notifications

@UIApplicationMain
@objc class AppDelegate: FlutterAppDelegate {
  override func application(
    _ application: UIApplication,
    didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?
  ) -> Bool {
    GeneratedPluginRegistrant.register(with: self)

    // Awesome Notifications 초기화
    SwiftAwesomeNotificationsPlugin.setPluginRegistrantCallback { registry in
      SwiftAwesomeNotificationsPlugin.register(
        with: registry.registrar(forPlugin: "SwiftAwesomeNotificationsPlugin")!
      )
    }

    return super.application(application, didFinishLaunchingWithOptions: launchOptions)
  }
}

import 'package:awesome_notifications/awesome_notifications.dart';
import 'package:flutter/material.dart';

class NotificationService {
  // 알림 채널 키 상수
  static const String basicChannelKey = 'basic_channel';
  static const String scheduledChannelKey = 'scheduled_channel';
  static const String chatChannelKey = 'chat_channel';

  // 초기화
  static Future<void> initialize() async {
    await AwesomeNotifications().initialize(
      // 앱 아이콘 (null이면 기본 아이콘 사용)
      null, // 'resource://drawable/app_icon'

      // 알림 채널 정의
      [
        // 기본 알림 채널
        NotificationChannel(
          channelKey: basicChannelKey,
          channelName: '기본 알림',
          channelDescription: '일반적인 앱 알림',
          defaultColor: Colors.blue,
          importance: NotificationImportance.High,
          channelShowBadge: true,
        ),

        // 예약 알림 채널
        NotificationChannel(
          channelKey: scheduledChannelKey,
          channelName: '예약 알림',
          channelDescription: '일정 및 리마인더 알림',
          defaultColor: Colors.orange,
          importance: NotificationImportance.High,
          ledColor: Colors.orange,
        ),

        // 채팅 알림 채널
        NotificationChannel(
          channelKey: chatChannelKey,
          channelName: '채팅',
          channelDescription: '새 메시지 알림',
          defaultColor: Colors.green,
          importance: NotificationImportance.Max,
          playSound: true,
          enableVibration: true,
        ),
      ],

      // 디버그 모드
      debug: true,
    );
  }

  // 알림 리스너 설정
  static Future<void> setListeners() async {
    // 알림 생성 시
    AwesomeNotifications().setListeners(
      // 알림이 생성되었을 때
      onNotificationCreatedMethod: onNotificationCreated,
      // 알림이 표시되었을 때
      onNotificationDisplayedMethod: onNotificationDisplayed,
      // 알림을 탭했을 때
      onActionReceivedMethod: onActionReceived,
      // 알림이 닫혔을 때
      onDismissActionReceivedMethod: onDismissActionReceived,
    );
  }

  // 콜백 메서드들 (반드시 static 또는 top-level 함수여야 함)
  @pragma('vm:entry-point')
  static Future<void> onNotificationCreated(
    ReceivedNotification receivedNotification,
  ) async {
    print('알림 생성됨: ${receivedNotification.title}');
  }

  @pragma('vm:entry-point')
  static Future<void> onNotificationDisplayed(
    ReceivedNotification receivedNotification,
  ) async {
    print('알림 표시됨: ${receivedNotification.title}');
  }

  @pragma('vm:entry-point')
  static Future<void> onActionReceived(
    ReceivedAction receivedAction,
  ) async {
    print('알림 액션: ${receivedAction.buttonKeyPressed}');

    // 특정 화면으로 이동 (예: payload 사용)
    final payload = receivedAction.payload;
    if (payload != null && payload['screen'] != null) {
      // 네비게이션 처리
      // navigatorKey.currentState?.pushNamed(payload['screen']!);
    }
  }

  @pragma('vm:entry-point')
  static Future<void> onDismissActionReceived(
    ReceivedAction receivedAction,
  ) async {
    print('알림 닫힘: ${receivedAction.id}');
  }

  // 권한 요청
  static Future<bool> requestPermission() async {
    final isAllowed = await AwesomeNotifications().isNotificationAllowed();
    if (!isAllowed) {
      return await AwesomeNotifications().requestPermissionToSendNotifications();
    }
    return true;
  }
}

// main.dart에서 초기화
void main() async {
  WidgetsFlutterBinding.ensureInitialized();

  // 알림 서비스 초기화
  await NotificationService.initialize();
  await NotificationService.setListeners();

  runApp(const MyApp());
}

import 'package:awesome_notifications/awesome_notifications.dart';
import 'notification_service.dart';

class NotificationExamples {
  // 기본 알림
  static Future<void> showBasicNotification() async {
    await AwesomeNotifications().createNotification(
      content: NotificationContent(
        id: 1,
        channelKey: NotificationService.basicChannelKey,
        title: '안녕하세요! 👋',
        body: '이것은 기본 알림입니다.',
        // 알림 탭 시 전달할 데이터
        payload: {'screen': '/home', 'id': '123'},
      ),
    );
  }

  // 큰 텍스트 알림
  static Future<void> showBigTextNotification() async {
    await AwesomeNotifications().createNotification(
      content: NotificationContent(
        id: 2,
        channelKey: NotificationService.basicChannelKey,
        title: '긴 내용 알림',
        body: '이것은 매우 긴 내용의 알림입니다. '
            '알림을 확장하면 전체 내용을 볼 수 있습니다. '
            '사용자에게 자세한 정보를 전달할 때 유용합니다.',
        notificationLayout: NotificationLayout.BigText,
      ),
    );
  }

  // 이미지 알림
  static Future<void> showImageNotification() async {
    await AwesomeNotifications().createNotification(
      content: NotificationContent(
        id: 3,
        channelKey: NotificationService.basicChannelKey,
        title: '새 상품 도착! 🎉',
        body: '지금 확인해보세요',
        notificationLayout: NotificationLayout.BigPicture,
        // 네트워크 이미지
        bigPicture: 'https://picsum.photos/400/200',
        // 큰 아이콘
        largeIcon: 'https://picsum.photos/100/100',
      ),
    );
  }

  // 인박스 스타일 (여러 줄)
  static Future<void> showInboxNotification() async {
    await AwesomeNotifications().createNotification(
      content: NotificationContent(
        id: 4,
        channelKey: NotificationService.chatChannelKey,
        title: '새 메시지 3개',
        body: '김철수: 안녕하세요\n이영희: 회의 시간 변경\n박지민: 확인했습니다',
        notificationLayout: NotificationLayout.Inbox,
        summary: '읽지 않은 메시지',
      ),
    );
  }

  // 프로그레스 바 알림
  static Future<void> showProgressNotification(int progress) async {
    await AwesomeNotifications().createNotification(
      content: NotificationContent(
        id: 5,
        channelKey: NotificationService.basicChannelKey,
        title: '다운로드 중...',
        body: '$progress% 완료',
        notificationLayout: NotificationLayout.ProgressBar,
        progress: progress.toDouble(),
        locked: true,  // 스와이프로 닫기 방지
      ),
    );
  }

  // 메시징 스타일 (채팅)
  static Future<void> showMessagingNotification() async {
    await AwesomeNotifications().createNotification(
      content: NotificationContent(
        id: 6,
        channelKey: NotificationService.chatChannelKey,
        title: '김철수',
        body: '점심 먹으러 갈래요?',
        notificationLayout: NotificationLayout.Messaging,
        largeIcon: 'https://i.pravatar.cc/100',
        summary: '채팅',
        category: NotificationCategory.Message,
      ),
    );
  }

  // 알림 취소
  static Future<void> cancelNotification(int id) async {
    await AwesomeNotifications().cancel(id);
  }

  // 모든 알림 취소
  static Future<void> cancelAllNotifications() async {
    await AwesomeNotifications().cancelAll();
  }
}

import 'package:awesome_notifications/awesome_notifications.dart';
import 'notification_service.dart';

class ActionNotificationExamples {
  // 기본 액션 버튼
  static Future<void> showWithActionButtons() async {
    await AwesomeNotifications().createNotification(
      content: NotificationContent(
        id: 10,
        channelKey: NotificationService.basicChannelKey,
        title: '새 친구 요청',
        body: '김철수님이 친구 요청을 보냈습니다.',
        largeIcon: 'https://i.pravatar.cc/100',
      ),
      actionButtons: [
        NotificationActionButton(
          key: 'ACCEPT',
          label: '수락',
          color: Colors.green,
          autoDismissible: true,  // 버튼 탭 시 알림 자동 닫힘
        ),
        NotificationActionButton(
          key: 'REJECT',
          label: '거절',
          color: Colors.red,
          autoDismissible: true,
          isDangerousOption: true,  // iOS에서 빨간색으로 표시
        ),
      ],
    );
  }

  // 텍스트 입력 버튼 (답장)
  static Future<void> showReplyNotification() async {
    await AwesomeNotifications().createNotification(
      content: NotificationContent(
        id: 11,
        channelKey: NotificationService.chatChannelKey,
        title: '김철수',
        body: '지금 어디야?',
        category: NotificationCategory.Message,
      ),
      actionButtons: [
        NotificationActionButton(
          key: 'REPLY',
          label: '답장',
          // 텍스트 입력 필드 표시
          requireInputText: true,
          autoDismissible: true,
        ),
        NotificationActionButton(
          key: 'MARK_READ',
          label: '읽음 표시',
          autoDismissible: true,
        ),
      ],
    );
  }

  // 미디어 컨트롤 (음악 플레이어)
  static Future<void> showMediaControlNotification() async {
    await AwesomeNotifications().createNotification(
      content: NotificationContent(
        id: 12,
        channelKey: NotificationService.basicChannelKey,
        title: 'Now Playing',
        body: 'Artist - Song Title',
        notificationLayout: NotificationLayout.MediaPlayer,
        largeIcon: 'https://picsum.photos/100/100',
        locked: true,
        category: NotificationCategory.Transport,
      ),
      actionButtons: [
        NotificationActionButton(
          key: 'PREV',
          label: '⏮️',
          showInCompactView: true,
          enabled: true,
        ),
        NotificationActionButton(
          key: 'PLAY_PAUSE',
          label: '⏸️',
          showInCompactView: true,
        ),
        NotificationActionButton(
          key: 'NEXT',
          label: '⏭️',
          showInCompactView: true,
        ),
      ],
    );
  }

  // 알람 스타일 (전체 화면)
  static Future<void> showAlarmNotification() async {
    await AwesomeNotifications().createNotification(
      content: NotificationContent(
        id: 13,
        channelKey: NotificationService.scheduledChannelKey,
        title: '⏰ 알람',
        body: '일어날 시간입니다!',
        category: NotificationCategory.Alarm,
        wakeUpScreen: true,  // 화면 켜기
        fullScreenIntent: true,  // 전체 화면으로 표시
        autoDismissible: false,
        locked: true,
      ),
      actionButtons: [
        NotificationActionButton(
          key: 'SNOOZE',
          label: '5분 후',
        ),
        NotificationActionButton(
          key: 'DISMISS',
          label: '해제',
          isDangerousOption: true,
        ),
      ],
    );
  }
}

// 액션 처리 (notification_service.dart의 onActionReceived에서)
@pragma('vm:entry-point')
static Future<void> onActionReceived(ReceivedAction receivedAction) async {
  final buttonKey = receivedAction.buttonKeyPressed;
  final payload = receivedAction.payload;
  final inputText = receivedAction.buttonKeyInput;  // 텍스트 입력값

  switch (buttonKey) {
    case 'ACCEPT':
      print('친구 요청 수락');
      // API 호출 등
      break;
    case 'REJECT':
      print('친구 요청 거절');
      break;
    case 'REPLY':
      print('답장 내용: $inputText');
      // 메시지 전송 처리
      break;
    case 'PLAY_PAUSE':
      print('재생/일시정지');
      // 오디오 플레이어 제어
      break;
    case 'SNOOZE':
      // 5분 후 다시 알람
      await _scheduleSnooze();
      break;
    default:
      // 알림 본체 탭 (버튼 아님)
      if (payload?['screen'] != null) {
        // 해당 화면으로 이동
      }
  }
}

import 'package:awesome_notifications/awesome_notifications.dart';
import 'notification_service.dart';

class ScheduledNotificationExamples {
  // 특정 시간에 알림 예약
  static Future<void> scheduleNotification({
    required int id,
    required String title,
    required String body,
    required DateTime scheduledDate,
  }) async {
    await AwesomeNotifications().createNotification(
      content: NotificationContent(
        id: id,
        channelKey: NotificationService.scheduledChannelKey,
        title: title,
        body: body,
        category: NotificationCategory.Reminder,
      ),
      schedule: NotificationCalendar.fromDate(
        date: scheduledDate,
        preciseAlarm: true,  // 정확한 시간에 알림
        allowWhileIdle: true,  // Doze 모드에서도 알림
      ),
    );
  }

  // 매일 특정 시간에 반복
  static Future<void> scheduleDailyReminder({
    required int id,
    required String title,
    required String body,
    required int hour,
    required int minute,
  }) async {
    await AwesomeNotifications().createNotification(
      content: NotificationContent(
        id: id,
        channelKey: NotificationService.scheduledChannelKey,
        title: title,
        body: body,
      ),
      schedule: NotificationCalendar(
        hour: hour,
        minute: minute,
        second: 0,
        repeats: true,  // 반복 활성화
        preciseAlarm: true,
      ),
    );
  }

  // 매주 특정 요일에 반복
  static Future<void> scheduleWeeklyReminder({
    required int id,
    required String title,
    required int weekday,  // 1=월요일, 7=일요일
    required int hour,
    required int minute,
  }) async {
    await AwesomeNotifications().createNotification(
      content: NotificationContent(
        id: id,
        channelKey: NotificationService.scheduledChannelKey,
        title: title,
        body: '매주 알림',
      ),
      schedule: NotificationCalendar(
        weekday: weekday,
        hour: hour,
        minute: minute,
        second: 0,
        repeats: true,
      ),
    );
  }

  // 일정 간격으로 반복 (예: 2시간마다)
  static Future<void> scheduleIntervalNotification({
    required int id,
    required String title,
    required Duration interval,
  }) async {
    await AwesomeNotifications().createNotification(
      content: NotificationContent(
        id: id,
        channelKey: NotificationService.scheduledChannelKey,
        title: title,
        body: '정기 알림',
      ),
      schedule: NotificationInterval(
        interval: interval.inSeconds,
        repeats: true,
        preciseAlarm: true,
      ),
    );
  }

  // 특정 조건의 알림 (예: 매월 1일)
  static Future<void> scheduleMonthlyNotification({
    required int id,
    required String title,
    required int day,  // 1-31
    required int hour,
  }) async {
    await AwesomeNotifications().createNotification(
      content: NotificationContent(
        id: id,
        channelKey: NotificationService.scheduledChannelKey,
        title: title,
        body: '매월 알림',
      ),
      schedule: NotificationCalendar(
        day: day,
        hour: hour,
        minute: 0,
        second: 0,
        repeats: true,
      ),
    );
  }

  // 예약된 알림 목록 조회
  static Future<List<NotificationModel>> getScheduledNotifications() async {
    return await AwesomeNotifications().listScheduledNotifications();
  }

  // 특정 예약 알림 취소
  static Future<void> cancelScheduledNotification(int id) async {
    await AwesomeNotifications().cancelSchedule(id);
  }

  // 모든 예약 알림 취소
  static Future<void> cancelAllScheduledNotifications() async {
    await AwesomeNotifications().cancelAllSchedules();
  }
}

// 사용 예시
void exampleUsage() async {
  // 내일 오전 9시에 알림
  await ScheduledNotificationExamples.scheduleNotification(
    id: 100,
    title: '내일 회의',
    body: '오전 10시 팀 회의가 있습니다.',
    scheduledDate: DateTime.now().add(const Duration(days: 1)).copyWith(
      hour: 9,
      minute: 0,
    ),
  );

  // 매일 오후 8시 복약 알림
  await ScheduledNotificationExamples.scheduleDailyReminder(
    id: 101,
    title: '💊 복약 시간',
    body: '약 드실 시간입니다.',
    hour: 20,
    minute: 0,
  );

  // 매주 월요일 오전 9시 주간 리뷰
  await ScheduledNotificationExamples.scheduleWeeklyReminder(
    id: 102,
    title: '📋 주간 리뷰',
    weekday: 1,  // 월요일
    hour: 9,
    minute: 0,
  );
}

