class NotificationIds {
  // 범위로 구분
  static const int chatBase = 1000;
  static const int reminderBase = 2000;
  static const int systemBase = 3000;

  // 사용
  static int chatNotification(String oderId) {
    return chatBase + oderId.hashCode.abs() % 1000;
  }
}

